mapper.select:
SELECT COUNT(*)
FROM wf_timeout_alert
WHERE alert_time >= #{startDate}
AND tenant_id = #{tenantId}

SELECT COUNT(*)
FROM wf_timeout_alert
WHERE timeout_level = #{alertLevel}
AND resolved = 'N'
AND tenant_id = #{tenantId}

SELECT ta.id, ta.tenant_id, ta.alert_type, ta.target_id, ta.target_name, ta.timeout_level, ta.timeout_duration, ta.threshold, ta.assignee_id, ta.assignee_name, ta.alert_time, ta.notification_sent, ta.escalated, ta.escalated_to_id, ta.escalated_to_name, ta.escalated_time, ta.resolved, ta.resolved_by_id, ta.resolved_by_name, ta.resolve_note, ta.resolve_time, ta.create_time, ta.update_time FROM wf_timeout_alert ta
ta.tenant_id = #{tenantId}
AND ta.alert_type = #{alertType}
AND ta.timeout_level = #{alertLevel}
AND ta.resolved = 'Y'
AND (ta.resolved = 'N' OR ta.resolved IS NULL)
ORDER BY ta.alert_time DESC

SELECT x.timeout_level AS level, COUNT(*) AS count FROM ( SELECT ta.timeout_level, pm.process_def_key FROM wf_timeout_alert ta JOIN wf_process_monitor pm ON ta.alert_type = 'PROCESS' AND pm.tenant_id = ta.tenant_id AND pm.instance_id = ta.target_id WHERE ta.tenant_id = #{tenantId} AND ta.alert_time >= #{startDate} AND ta.alert_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY) UNION ALL SELECT ta.timeout_level, pm.process_def_key FROM wf_timeout_alert ta JOIN wf_task_monitor tm ON ta.alert_type = 'TASK' AND tm.tenant_id = ta.tenant_id AND tm.task_id = ta.target_id JOIN wf_process_monitor pm ON pm.tenant_id = tm.tenant_id AND pm.instance_id = tm.instance_id WHERE ta.tenant_id = #{tenantId} AND ta.alert_time >= #{startDate} AND ta.alert_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY) ) x
x.process_def_key = #{processDefKey}
GROUP BY x.timeout_level ORDER BY FIELD(x.timeout_level, 'REMIND', 'WARNING', 'CRITICAL')
